cat > $TMPDIR/find_uaf.py <<'PYEOF'
#!/usr/bin/env python3
"""Find functions where a pointer into skb data is saved before a pskb_may_pull-like call
and used after it, in the same function."""
import re, os, sys, subprocess

ROOT = "/mnt/raid/home/yangshuangning/vuln_variant_search/experiments/clairvoyant_variant_search/runs/C6/public/snapshots/s03"

pull_fns = re.compile(r'\b(pskb_may_pull(?:_reason)?|__pskb_pull(?:_tail)?|pskb_pull|pskb_pull_tcp)\s*\(')

def function_ranges(path):
    """Yield (start_line, end_line, body_lines) for each top-level function."""
    try:
        with open(path, 'r', errors='replace') as f:
            lines = f.readlines()
    except OSError:
        return
    i = 0
    n = len(lines)
    while i < n:
        # crude function start: line at col0 ending with '{' or a signature line
        m = re.match(r'^[A-Za-z_][A-Za-z0-9_ \t\*\(\),]*\)\s*$', lines[i])
        if m and i+1 < n and lines[i+1].strip() == '{':
            start = i
            depth = 0
            j = i + 1
            while j < n:
                depth += lines[j].count('{') - lines[j].count('}')
                if depth == 0:
                    break
                j += 1
            yield (start, j, lines[start:j+1])
            i = j + 1
        else:
            i += 1

def analyze(path, out):
    try:
        with open(path, 'r', errors='replace') as f:
            src = f.read()
    except OSError:
        return
    lines = src.split('\n')
    # find function boundaries more robustly using ctags-like brace matching from col-0 braces
    func_spans = []
    i = 0
    n = len(lines)
    while i < n:
        line = lines[i]
        # top-level open brace at column 0
        if line.startswith('{') and i > 0:
            # function body opener; find matching close
            depth = 0
            j = i
            while j < n:
                # strip strings/comments crudely
                depth += lines[j].count('{') - lines[j].count('}')
                if depth <= 0:
                    break
                j += 1
            # signature: scan back up to 6 lines
            sig_start = i - 1
            k = i - 1
            while k >= 0 and k >= i - 8 and lines[k].strip() != '' and not lines[k].startswith('#'):
                if lines[k].rstrip().endswith(')') or lines[k].rstrip().endswith(','):
                    sig_start = k
                if lines[k].rstrip().endswith('{') or '(' in lines[k] and lines[k].rstrip().endswith(')'):
                    pass
                k -= 1
            func_spans.append((sig_start, j, lines[sig_start:j+1]))
            i = j + 1
        else:
            i += 1
    for (sig, end, body) in func_spans:
        pull_idx = [k for k, l in enumerate(body) if pull_fns.search(l)]
        if not pull_idx:
            continue
        fname_m = re.search(r'([A-Za-z_][A-Za-z0-9_]*)\s*\(', body[0]) if body else None
        fname = fname_m.group(1) if fname_m else '?'
        # pointer-derived-from-skb patterns
        ptr_decl = re.compile(
            r'\b([A-Za-z_][A-Za-z0-9_]*)\s*(?::\s*[A-Za-z_][A-Za-z0-9_:]*\s*)?=\s*('
            r'skb_header_pointer\s*\(|'
            r'skb->data\b|'
            r'\w+->data\b|'
            r'skb_network_header\s*\(|skb_transport_header\s*\(|skb_mac_header\s*\(|'
            r'skb_(?:vlan_)?eth_hdr\s*\(|skb_(?:ip|ipv6|tcp|udp|sctp|icmp|igmp|arp|th|nh)h\s*\('
            r')')
        for k, l in enumerate(body):
            for m in ptr_decl.finditer(l):
                var = m.group(1)
                decl_line = k
                for p in pull_idx:
                    if decl_line < p:
                        # check uses after pull
                        for u in range(p+1, len(body)):
                            ul = body[u]
                            # deref or use of var
                            for um in re.finditer(r'\b' + re.escape(var) + r'\b', ul):
                                # check for refetch assignment before use
                                between = body[p+1:u]
                                refetched = any(re.search(r'\b' + re.escape(var) + r'\s*=', bl) for bl in between)
                                if refetched:
                                    break
                                # use is a real use (not just declaration of another var)
                                if re.search(r'[-\w]\s*' + re.escape(var) + r'\b', ul):
                                    continue
                                out.append((path, sig+1, fname, var, decl_line+sig+1, p+sig+1, u+sig+1, l.strip(), body[p].strip(), ul.strip()))
                                break
                            else:
                                continue
                            break

results = []
targets = []
for dirpath, dirnames, filenames in os.walk(os.path.join(ROOT, 'net')):
    for fn in filenames:
        if fn.endswith(('.c',)):
            targets.append(os.path.join(dirpath, fn))
for dirpath, dirnames, filenames in os.walk(os.path.join(ROOT, 'drivers')):
    if '/net' not in dirpath and 'ethernet' not in dirpath and 'hsi' not in dirpath and 'scsi' not in dirpath:
        continue
    for fn in filenames:
        if fn.endswith('.c'):
            targets.append(os.path.join(dirpath, fn))

for t in sorted(targets):
    analyze(t, results)

# dedupe
seen = set()
uniq = []
for r in results:
    key = (r[0], r[1], r[3], r[6])
    if key in seen:
        continue
    seen.add(key)
    uniq.append(r)

print(f"total candidate uses: {len(uniq)}")
for r in uniq:
    rel = os.path.relpath(r[0], ROOT)
    print(f"\n=== {rel}:{r[1]} func={r[2]} var={r[3]}")
    print(f"  save@{r[4]}: {r[7]}")
    print(f"  pull@{r[5]}: {r[8]}")
    print(f"  use @{r[6]}: {r[9]}")
