#!/usr/bin/env python3
"""Heuristic scanner for pull-invalidates-pointer: within a function, find
assignments of data-derived pointers, a subsequent pskb_may_pull*/pskb_pull* call,
and a later use of that same pointer."""
import re, sys, os, subprocess

roots = sys.argv[1:]
srcs = subprocess.run(
    ["grep", "-rl", "pskb_may_pull", "--include=*.c", *roots],
    capture_output=True, text=True).stdout.split()

pull_re = re.compile(r'\b(pskb_may_pull|pskb_may_pull_reason|__pskb_pull_tail|pskb_pull|__pskb_pull|skb_pull|pskb_trim|pskb_expand_head|skb_cow|skb_cow_head|__skb_linearize|skb_linearize)\s*\(')
# things that define a "derived pointer" variable
def_re = re.compile(r'^\s*(?:const\s+)?(?:struct\s+)?\w[\w\s\*]*?\*?\s*(\w+)\s*=\s*([A-Za-z_].*?);')
deref_re = re.compile(r'\b(\w+)\s*(->|\.)|->\s*(\w+)')
name_re = re.compile(r'^[A-Za-z_]\w*$')

def find_funcs(lines):
    """yield (start,end) 0-based line ranges of top-level functions (column-0 brace scoping)."""
    starts = []
    cur = None
    for i, ln in enumerate(lines):
        if ln.startswith('{') and cur is None:
            cur = i
        if ln.startswith('}') and cur is not None:
            starts.append((cur, i))
            cur = None
    return starts

report = []
for path in srcs:
    try:
        text = open(path, encoding='utf-8', errors='replace').read()
    except OSError:
        continue
    lines = text.split('\n')
    for (fs, fe) in find_funcs(lines):
        if fe - fs > 400 or fe - fs < 4:
            continue
        body = lines[fs:fe+1]
        # find pull calls
        pull_lines = [(i, l) for i, l in enumerate(body) if pull_re.search(l)]
        if not pull_lines:
            continue
        # candidate pointer names: variables assigned from skb-derived expressions
        cands = {}
        for i, l in enumerate(body):
            m = def_re.match(l)
            if not m:
                continue
            name, expr = m.group(1), m.group(2)
            if not name_re.match(name):
                continue
            # expressions derived from the skb data area
            if re.search(r'skb(?:->|\s*[\.\)]?\s*\w*\s*\+)|skb_header_pointer|skb_network_header|skb_transport_header|skb_mac_header|->data\b|skb_tail_pointer|skb->head\b', expr) or 'skb_header_pointer' in expr:
                cands.setdefault(name, i)
        if not cands:
            continue
        for pi, pl in pull_lines:
            for name, defi in cands.items():
                if defi >= pi:
                    continue
                # uses after pull: identifier used (not just declared)
                for j in range(pi+1, len(body)):
                    l = body[j]
                    if re.search(r'\b' + re.escape(name) + r'\b', l):
                        # skip pure re-assignment of the same var (that's a refetch)
                        if re.match(r'^\s*(?:const\s+)?[\w\s\*]*\*\s*' + re.escape(name) + r'\s*=', l):
                            continue
                        report.append((path, fs+defi+1, body[defi].strip(),
                                       fs+pi+1, pl.strip(), fs+j+1, l.strip(),
                                       lines[fs].strip()[:70]))
                        break
for r in report:
    print('\t'.join(str(x) for x in r))
