390			if (unlikely(ntohs(ipv6h->payload_len) < encap))
391				return -EINVAL;
392	
393			ipv6h->nexthdr = psph->nexthdr;
394			ipv6h->payload_len = htons(ntohs(ipv6h->payload_len) - encap);
