import re, os, sys

root = "."
pull_re = re.compile(r'\b(pskb_may_pull|pskb_may_pull_reason|__pskb_pull_tail|__pskb_pull|pskb_pull|skb_pull|pskb_expand_head|skb_linearize|skb_cow_head|skb_cow)\s*\(')

# heuristic ptr-into-skb patterns
ptr_assign_re = re.compile(
    r'^[^=]*=\s*(?:\([^)]*\*\)\s*)?(skb->data|skb_header_pointer\s*\(|skb_network_header\s*\(|skb_transport_header\s*\(|skb_mac_header\s*\(|\w+->data\b)'
)

results = []

for dirpath, dirnames, filenames in os.walk(root):
    for fn in filenames:
        if not fn.endswith(('.c', '.h')):
            continue
        path = os.path.join(dirpath, fn)
        try:
            lines = open(path, encoding='utf-8', errors='replace').read().splitlines()
        except Exception:
            continue
        # find function boundaries: lines starting with '{' or '}' at col 0
        funcs = []  # (start_idx, end_idx)
        start = None
        for i, l in enumerate(lines):
            if l.startswith('{'):
                if start is None:
                    start = i
            elif l.startswith('}'):
                if start is not None:
                    funcs.append((start, i))
                    start = None
        if start is not None:
            funcs.append((start, len(lines)-1))
        for (s, e) in funcs:
            body = lines[s:e+1]
            pull_lines = [j for j, l in enumerate(body) if pull_re.search(l)]
            if not pull_lines:
                continue
            # find pointer assignments into skb data
            ptrs = {}  # varname -> list of line offsets in body
            var_re = re.compile(r'^\s*(?:const\s+)?(?:struct\s+)?[\w]+\s*\*?\s*\**\s*(\w+)\s*=\s*(skb_header_pointer\s*\(|[A-Za-z_]\w*->data\b|skb_network_header\s*\(|skb_transport_header\s*\(|skb_mac_header\s*\(|skb_mac_header\s*\+|skb->data|skb->head|skb_network_offset)')
            for j, l in enumerate(body):
                m = var_re.match(l)
                if m:
                    ptrs.setdefault(m.group(1), []).append(j)
            if not ptrs:
                continue
            for pl in pull_lines:
                pull_stmt = body[pl]
                # find skb variable name (first arg)
                pm = re.search(pull_re, pull_stmt)
                # for each pointer var, check use after pull line
                for var, deflines in ptrs.items():
                    # def before pull (strictly), use after
                    for d in deflines:
                        if d < pl:
                            for k in range(pl+1, len(body)):
                                l = body[k]
                                if re.search(r'\b%s\b' % re.escape(var), l):
                                    # skip lines that redefine
                                    if re.match(r'^\s*(?:const\s+)?[\w]+\s*\*?\s*\**\s*%s\s*=' % re.escape(var), l):
                                        continue
                                    results.append((path, s+1+d, s+1+pl, s+1+k, var, lines[s+d].strip(), pull_stmt.strip(), l.strip()))
                                    break
for r in results:
    print('\t'.join(str(x) for x in r))
