cat > $TMPDIR/scan2.py << 'PYEOF'
import re, os

pull_re = re.compile(r'\b(pskb_may_pull|pskb_may_pull_reason|__pskb_pull_tail|__pskb_pull|pskb_pull|pskb_expand_head|skb_linearize|skb_cow_head|skb_cow)\s*\(')

# RHS patterns that derive a pointer from skb data
rhs_re = re.compile(
    r'=\s*(?:\([^)]*\*[^)]*\)\s*)?((?:[A-Za-z_]\w*->data)\b|skb_header_pointer\s*\(|skb->data\b|skb_network_header\s*\(|skb_transport_header\s*\(|skb_mac_header\s*\(|\w+->head\b)'
)
# var being assigned: take token before '='
results = []

for dirpath, dirnames, filenames in os.walk('.'):
    for fn in filenames:
        if not fn.endswith(('.c', '.h')):
            continue
        path = os.path.join(dirpath, fn)
        try:
            lines = open(path, encoding='utf-8', errors='replace').read().splitlines()
        except Exception:
            continue
        funcs = []
        start = None
        for i, l in enumerate(lines):
            if l.startswith('{'):
                if start is None:
                    start = i
            elif l.startswith('}'):
                if start is not None:
                    funcs.append((start, i))
                    start = None
        if start is not None:
            funcs.append((start, len(lines)-1))
        for (s, e) in funcs:
            body = lines[s:e+1]
            pull_lines = [j for j, l in enumerate(body) if pull_re.search(l)]
            if not pull_lines:
                continue
            ptrs = {}
            for j, l in enumerate(body):
                for m in re.finditer(r'([A-Za-z_]\w*)\s*(?:\[[^\]]*\])?\s*=\s*(?:\([^)]*\*[^)]*\)\s*)?((?:[A-Za-z_]\w*->data)\b|skb_header_pointer\s*\(|skb->data\b|skb_network_header\s*\(|skb_transport_header\s*\(|skb_mac_header\s*\(|[A-Za-z_]\w*->head\b)', l):
                    var, rhs = m.group(1), m.group(2)
                    # skip pure integer offsets assignments
                    if rhs.endswith('->data') or rhs.startswith('skb_header_pointer') or rhs == 'skb->data' or 'header' in rhs or rhs.endswith('->head'):
                        ptrs.setdefault(var, []).append(j)
            if not ptrs:
                continue
            for pl in pull_lines:
                pull_stmt = body[pl]
                for var, deflines in ptrs.items():
                    for d in deflines:
                        if d < pl:
                            for k in range(pl+1, len(body)):
                                l = body[k]
                                if re.search(r'\b%s\b' % re.escape(var), l):
                                    if re.match(r'^\s*(?:const\s+)?[\w\s\*]+\**\s*%s\s*=' % re.escape(var), l) and '->data' in l.split('=')[1]:
                                        continue
                                    results.append((path, s+1+d, s+1+pl, s+1+k, var, lines[s+d].strip(), pull_stmt.strip(), l.strip()))
                                    break
for r in results:
    print('\t'.join(str(x) for x in r))
