    while i < n:
        line = lines[i]
        m = re.match(r'^(\w[\w \t\*]*)\([^;]*$', line)
        if m and not line.strip().startswith(('#', '//', '*', '/*')) and not re.match(r'^(if|for|while|switch|return|sizeof|EXPORT)', line.strip()):
            name = line.strip().split('(')[0].split()[-1] if line.strip().split('(')[0].split() else '?'
            # find opening brace
            j = i
            while j < n and '{' not in lines[j] and ';' not in lines[j]:
                j += 1
            if j < n and '{' in lines[j]:
                # find matching close at column 0
                k = j + 1
                depth = lines[j].count('{') - lines[j].count('}')
                while k < n and depth > 0:
                    depth += lines[k].count('{') - lines[k].count('}')
                    k += 1
                yield name, i+1, k, lines[i:k]
                i = k
                continue
        i += 1

def analyze(path):
    try:
        for name, start, end, body in functions(path):
            text = ''.join(body)
            pulls = [(idx, l) for idx, l in enumerate(body) if pullre.search(l)]
            if not pulls:
                continue
            for pi, pline in pulls:
                # find pointer assignments before pull within function
                for idx in range(0, pi):
                    l = body[idx]
                    dm = re.match(r'^\s*(?:const\s+)?(?:struct\s+)?[\w]+\s*\*+\s*(\w+)\s*=\s*(.+);', l)
                    if not dm: continue
                    var, rhs = dm.group(1), dm.group(2)
                    if any(t in rhs for t in interesting) or re.search(r'\(\s*struct\s+\w+\s*\*\s*\)\s*skb', rhs):
                        # check use after pull
                        for uidx in range(pi+1, len(body)):
                            ul = body[uidx]
                            if re.search(r'\b'+re.escape(var)+r'\b', ul):
                                # skip re-assignments of var itself
                                if re.match(r'^\s*(?:const\s+)?[\w\s\*]*'+re.escape(var)+r'\s*=', ul):
                                    break
                                if '/*' in ul or ul.strip().startswith('*'):
                                    continue
                                print(f"{os.path.relpath(path, root)}:{start+uidx}\tFUNC {name}@{start}\tVAR {var}\tPULL@{start+pi}: {pline.strip()}\tUSE: {ul.strip()}")
                                break
    except Exception as e:
        pass

for dirpath, dirnames, filenames in os.walk(root):
    for fn in filenames:
        if fn.endswith('.c'):
            analyze(os.path.join(dirpath, fn))
