import os, re, sys
root = sys.argv[1]
pullre = re.compile(r'\b(pskb_may_pull(?:_reason)?|pskb_pull|__pskb_pull(?:_tail|_head)?)\s*\(')
# plain assignment: var = <rhs containing skb data derivation>
assign = re.compile(r'^\s*(\w+)\s*=\s*([^;]+);')
interesting = ('skb->data', 'skb_header_pointer(', 'skb_network_header(', 'skb_transport_header(', 'skb_mac_header(', 'skb_tail_pointer(', 'skb->head', 'skb_push(', 'skb_put(')
typedecl = re.compile(r'^\s*(?:const\s+)?(?:struct\s+)?[\w]+\s*\*+\s*(\w+)\s*(?:=[^;]*)?;')
def functions(path):
    with open(path, 'r', errors='replace') as f:
        lines = f.readlines()
    i, n = 0, len(lines)
    while i < n:
        line = lines[i]
        m = re.match(r'^(\w[\w \t\*]*)\([^;]*$', line)
        if m and not line.strip().startswith(('#','//','*','/*')) and not re.match(r'^(if|for|while|switch|return|sizeof|EXPORT)', line.strip()):
            j = i
            while j < n and '{' not in lines[j] and ';' not in lines[j]:
                j += 1
            if j < n and '{' in lines[j]:
                k = j + 1
                depth = lines[j].count('{') - lines[j].count('}')
                while k < n and depth > 0:
                    depth += lines[k].count('{') - lines[k].count('}')
                    k += 1
                yield i+1, k, lines[i:k]
                i = k
                continue
        i += 1

for dirpath, dirnames, filenames in os.walk(root):
    for fn in filenames:
        if not fn.endswith('.c'): continue
        path = os.path.join(dirpath, fn)
        try:
            for start, end, body in functions(path):
                pulls = [i for i,l in enumerate(body) if pullre.search(l)]
                if not pulls: continue
                ptrvars = set()
                for l in body:
                    for t in typedecl.finditer(l):
                        ptrvars.add(t.group(1))
                for pi in pulls:
                    for idx in range(0, pi):
                        am = assign.match(body[idx])
                        if not am: continue
                        var, rhs = am.group(1), am.group(2)
                        if var not in ptrvars: continue
                        if not (any(t in rhs for t in interesting) or re.search(r'\(\s*(?:const\s+)?struct\s+\w+\s*\*\s*\)\s*\*?skb', rhs)):
                            continue
                        if '==' in rhs or '!=' in rhs or 'if' in rhs: continue
                        for uidx in range(pi+1, len(body)):
                            ul = body[uidx]
                            if re.search(r'\b'+re.escape(var)+r'\s*=[^=]', ul):
                                break  # reassigned
                            if re.search(r'\b'+re.escape(var)+r'\b', ul) and not re.search(r'\b'+re.escape(var)+r'\s*=[^=]', ul):
                                if ul.strip().startswith('*') and '*/' not in ul and not re.match(r'^\*\s*\w', ul.strip()):
                                    continue
                                print(f"{os.path.relpath(path, root)}:{start+uidx}\tFUNC@{start}\tVAR {var}\tPULL@{start+pi}: {body[pi].strip()}\tSAVE@{start+idx}: {body[idx].strip()}\tUSE: {ul.strip()}")
                                break
        except Exception:
            pass
